import{y as t,b as a,c as o,X as r}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const p=JSON.parse('{"title":"Fallback Control Plane","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/FALLBACK_POLICY.md","filePath":"contracts/FALLBACK_POLICY.md","lastUpdated":1771753292000}'),l={name:"contracts/FALLBACK_POLICY.md"};function d(i,e,n,c,s,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="fallback-control-plane" tabindex="-1">Fallback Control Plane <a class="header-anchor" href="#fallback-control-plane" aria-label="Permalink to &quot;Fallback Control Plane&quot;">​</a></h1><p>undefined<strong>Status:</strong> Authoritative undefined<strong>Date:</strong> 2026-02-14 undefined<strong>Scope:</strong> Normalization fallback policy for MCP and CLI</p><hr><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to &quot;1. Purpose&quot;">​</a></h2><p>When agent output cannot be normalized via a provider adapter (XML, JSON, etc.), thegent falls back to plain-text extraction. This document defines the <strong>fallback control plane</strong>: policy, observability, and guardrails that govern when fallback is acceptable.</p><hr><h2 id="_2-policy-configuration" tabindex="-1">2. Policy Configuration <a class="header-anchor" href="#_2-policy-configuration" aria-label="Permalink to &quot;2. Policy Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Config</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>THGENT_NORMALIZATION_POLICY_ALLOW_FALLBACK</code></td><td>true</td><td>Allow plain-text fallback when adapter fails</td></tr><tr><td><code>THGENT_NORMALIZATION_POLICY_MIN_CONFIDENCE</code></td><td>0.4</td><td>Minimum confidence threshold; below triggers policy violation</td></tr><tr><td><code>THGENT_NORMALIZATION_POLICY_MAX_FALLBACK_RATE</code></td><td>0.3</td><td>Max global fallback rate (30%); above triggers policy violation</td></tr><tr><td><code>THGENT_NORMALIZATION_POLICY_STRICT_PROVIDERS</code></td><td>&quot;&quot;</td><td>Comma-separated providers that must never use fallback</td></tr></tbody></table><hr><h2 id="_3-fallback-flow" tabindex="-1">3. Fallback Flow <a class="header-anchor" href="#_3-fallback-flow" aria-label="Permalink to &quot;3. Fallback Flow&quot;">​</a></h2><ol><li>undefined<strong>Adapter attempt:</strong> Provider adapter (e.g. XMLOutputAdapter for gemini) normalizes raw output.</li><li>undefined<strong>On failure:</strong> If adapter throws or returns parse_errors, fallback is considered.</li><li>undefined<strong>Fallback:</strong> <code>extract_condensed()</code> produces a minimal CSM with <code>source_contract=&quot;fallback-plain&quot;</code>, confidence 0.3–0.5.</li><li>undefined<strong>Policy evaluation:</strong> <code>evaluate_fallback()</code> checks strict providers, confidence, global fallback rate.</li><li>undefined<strong>Telemetry:</strong> <code>ContractTelemetry.record_normalization()</code> records fallback events for observability.</li></ol><hr><h2 id="_4-mcp-and-cli-parity" tabindex="-1">4. MCP and CLI Parity <a class="header-anchor" href="#_4-mcp-and-cli-parity" aria-label="Permalink to &quot;4. MCP and CLI Parity&quot;">​</a></h2><p>Both MCP <code>thegent_run</code> and CLI <code>thegent run</code> use the same <code>run_with_failover</code> path, which:</p><ul><li>Calls <code>normalize_output(agent, raw)</code> after each run</li><li>Evaluates <code>evaluate_fallback()</code> with config-driven <code>FallbackPolicy</code></li><li>Records to <code>ContractTelemetry</code> for drift detection</li></ul><p>undefined<strong>MCP fallback policy</strong> = same as CLI; no separate MCP-specific policy.</p><hr><h2 id="_5-observability" tabindex="-1">5. Observability <a class="header-anchor" href="#_5-observability" aria-label="Permalink to &quot;5. Observability&quot;">​</a></h2><ul><li>undefined<strong>ContractTelemetry:</strong> Tracks fallback rate per provider and globally.</li><li>undefined<strong>Drift detection:</strong> <code>detect_drift()</code> flags significant fallback rate increases.</li><li>undefined<strong>Fallback KPIs (G-CA-02 B3):</strong> <code>get_fallback_kpis()</code> returns structured metrics; <code>thegent observe kpis</code> for dashboard/alerting.</li><li>undefined<strong>Parser-quality routing (G-CA-02 B2):</strong> <code>rank_providers_by_parser_quality()</code> orders providers by confidence/fallback; enabled via <code>THGENT_ROUTING_PARSER_QUALITY_ENABLED</code>.</li><li>undefined<strong>Session dir:</strong> Telemetry stored under <code>THGENT_SESSION_DIR</code> (default <code>.thegent/sessions</code>).</li></ul><hr><h2 id="_6-guardrails" tabindex="-1">6. Guardrails <a class="header-anchor" href="#_6-guardrails" aria-label="Permalink to &quot;6. Guardrails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guardrail</th><th>Behavior</th></tr></thead><tbody><tr><td>Critical lane (G-CA-03 C3)</td><td><code>--lane critical</code> rejects runs with <code>source_contract</code> fallback-plain or unknown; run fails with error_class unknown_contract.</td></tr><tr><td>Strict provider</td><td>If provider in <code>strict_providers</code>, fallback is blocked; <code>SemanticValidationError</code> raised when <code>allow_fallback=False</code>.</td></tr><tr><td>Confidence threshold</td><td>Below <code>min_confidence_threshold</code> → policy violation logged.</td></tr><tr><td>Max fallback rate</td><td>Global rate &gt; <code>max_fallback_rate</code> → policy violation logged.</td></tr><tr><td>Parse error class</td><td><code>parse_truncated</code> from <code>extract_condensed_validated</code> → adapter result returned (no fallback to COMPLETED).</td></tr></tbody></table><hr><h2 id="_7-implementation" tabindex="-1">7. Implementation <a class="header-anchor" href="#_7-implementation" aria-label="Permalink to &quot;7. Implementation&quot;">​</a></h2><ul><li>undefined<strong>Policy:</strong> <code>src/thegent/contracts/policy.py</code> — <code>FallbackPolicy</code>, <code>evaluate_fallback</code></li><li>undefined<strong>Config:</strong> <code>src/thegent/config.py</code> — <code>normalization_policy_*</code></li><li>undefined<strong>Telemetry:</strong> <code>src/thegent/contracts/telemetry.py</code> — <code>ContractTelemetry</code></li><li>undefined<strong>Usage:</strong> <code>src/thegent/cli_impl.py</code> — <code>run_with_failover</code></li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li><li><a href="./PROVIDER_ADAPTER_CONTRACTS.html">PROVIDER_ADAPTER_CONTRACTS.md</a> — adapter contracts</li></ul>',28)])])}const b=t(l,[["render",d]]);export{p as __pageData,b as default};
